-- Daily challenges for 2026-11-17: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-17. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('making-space-for-hope', 'Making Space for Hope', 'For anyone who wants a little more to look forward to. Each day is one small way to notice what is going right, plan something good and keep a hopeful thought within reach, even on gray days.', 'Wellbeing', 365, array['Resilience', 'Motivation']::text[], 1, '2026-11-17T17:00:00+00:00'::timestamptz),
  ('keeping-traditions-alive', 'Keeping Traditions Alive', 'For anyone who wants the rituals that tie people together to stay alive, or to start new ones. Each day is one small way to honor, share or create a tradition with family, friends or yourself.', 'Connection', 365, array['Family', 'Relationships', 'Values']::text[], 1, '2026-11-17T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('making-space-for-hope', 'keeping-traditions-alive');

